<script setup lang="ts">
import {ref,onMounted,computed} from 'vue';
import {useRoute,useRouter} from 'vue-router';
import type {QuestionVersion,SurveySummary,Page,CrossStatistics,CrossPage,CrossAnswer} from '@survey/shared';
import {api,RequestError} from '../api';
import {queryPage} from '../library-client';
const route=useRoute(),router=useRouter(),questionId=ref(String(route.params.questionId??'')),versionId=ref(String(route.query.versionId??'')),versions=ref<QuestionVersion[]>([]),versionCursor=ref<string|null>(null),surveys=ref<SurveySummary[]>([]),surveyCursor=ref<string|null>(null),selected=ref<string[]>([]),scope=ref('all'),boundaries=ref(''),summary=ref<CrossStatistics|null>(null),raw=ref<CrossAnswer[]>([]),frequency=ref<{value:string;count:number}[]>([]),answerCursor=ref<string|null>(null),frequencyCursor=ref<string|null>(null),asOf=ref(''),busy=ref(false),error=ref(''),needsReload=ref(false);
const version=computed(()=>versions.value.find(v=>v.id===versionId.value)),root=computed(()=>`/question-statistics/${questionId.value}/versions/${versionId.value}`);
// Keep only type evidence from a successful authorized summary, scoped to its exact question/version.
const resolvedType=ref<{questionId:string;versionId:string;number:boolean}|null>(null);
const isNumber=computed(()=>version.value?version.value.content.type==='number':resolvedType.value?.questionId===questionId.value&&resolvedType.value?.versionId===versionId.value&&resolvedType.value.number);
const filter=()=>({surveyIds:scope.value==='selected'?selected.value.slice().sort().join(','):undefined});
function fail(e:unknown){error.value=(e as Error).message;needsReload.value=e instanceof RequestError&&e.code==='REPORT_SNAPSHOT_EXPIRED';}
async function loadVersions(more=false){try{const p=await api<Page<QuestionVersion>>(`/questions/${questionId.value}/versions`+queryPage({limit:'20',cursor:more?versionCursor.value??undefined:undefined}));versions.value=more?[...versions.value,...p.items]:p.items;versionCursor.value=p.nextCursor;if(!versionId.value)versionId.value=versions.value[0]?.id??'';}catch(e){fail(e);}}
async function loadSurveys(more=false){try{const p=await api<Page<SurveySummary>>('/surveys'+queryPage({limit:'100',cursor:more?surveyCursor.value??undefined:undefined}));surveys.value=more?[...surveys.value,...p.items]:p.items;surveyCursor.value=p.nextCursor;}catch(e){fail(e);}}
async function page(kind:'answers'|'distribution',more=false){const p=await api<CrossPage<CrossAnswer|{value:string;count:number}>>(root.value+'/'+kind+queryPage({...filter(),limit:'20',cursor:more?(kind==='answers'?answerCursor.value:frequencyCursor.value)??undefined:undefined}));asOf.value=p.asOf;if(kind==='answers'){raw.value=more?[...raw.value,...p.items as CrossAnswer[]]:p.items as CrossAnswer[];answerCursor.value=p.nextCursor;}else{frequency.value=more?[...frequency.value,...p.items as {value:string;count:number}[]]:p.items as {value:string;count:number}[];frequencyCursor.value=p.nextCursor;}}
async function run(){if(!versionId.value||scope.value==='selected'&&!selected.value.length){error.value='请选择正式版本及至少一份本人问卷。';return;}busy.value=true;error.value='';needsReload.value=false;summary.value=null;raw.value=[];frequency.value=[];answerCursor.value=frequencyCursor.value=null;try{summary.value=await api<CrossStatistics>(root.value+queryPage({...filter(),boundaries:isNumber.value?boundaries.value.trim()||undefined:undefined}));resolvedType.value={questionId:summary.value.questionId,versionId:summary.value.versionId,number:'average' in summary.value};if(!('optionCounts' in summary.value))await page('answers');if('average' in summary.value)await page('distribution');}catch(e){fail(e);}finally{busy.value=false;}}
async function more(kind:'answers'|'distribution'){busy.value=true;error.value='';try{await page(kind,true);}catch(e){fail(e);}finally{busy.value=false;}}
onMounted(async()=>{await loadVersions();await loadSurveys();if(versionId.value)await run();});
</script>
<template><section class="report-page"><RouterLink class="back" to="/questions">← 返回题目</RouterLink><h1 tabindex="-1">跨问卷题目统计</h1><p class="muted">只统计本人问卷中同一道题的同一正式版本，按真实回答份数计数；跳过、未回答均不补零。原分问卷统计保持独立。</p>
<form class="panel cross-controls" @submit.prevent="run"><fieldset :disabled="busy"><label for="cross-version">固定正式版本</label><select id="cross-version" v-model="versionId"><option v-for="v in versions" :key="v.id" :value="v.id">v{{v.version}} · {{v.content.title}}</option><option v-if="versionId&&!versions.some(v=>v.id===versionId)" :value="versionId">已保存引用的固定版本</option></select><button v-if="versionCursor" type="button" class="quiet" @click="loadVersions(true)">更多正式版本</button><label for="cross-scope">本人问卷范围</label><select id="cross-scope" v-model="scope"><option value="all">全部本人问卷</option><option value="selected">指定本人问卷</option></select><fieldset v-if="scope==='selected'"><legend>选择问卷（最多100份）</legend><label v-for="s in surveys" :key="s.id" class="check"><input v-model="selected" type="checkbox" :value="s.id">{{s.title}}</label><button v-if="surveyCursor" type="button" class="quiet" @click="loadSurveys(true)">更多本人问卷</button></fieldset><template v-if="isNumber"><label for="cross-boundaries">数值区间边界（逗号分隔，可留空）</label><input id="cross-boundaries" v-model="boundaries" placeholder="0,18,30,121"><small>欠界、左闭右开、最后区间闭右端及超界均单独计数。</small></template><button class="primary" :disabled="!versionId">查询本人范围</button></fieldset></form>
<p v-if="error" role="alert" class="error">{{error}} <button class="quiet" @click="run">{{needsReload?'重新查询第一页':'重新查询'}}</button></p><p v-if="busy" aria-busy="true" role="status">正在核对历史定义并统计…</p>
<template v-if="summary"><div class="count-strip panel"><div>问卷<strong data-testid="cross-surveys">{{summary.surveyCount}} 份</strong></div><div>符合范围答卷<strong>{{summary.eligibleResponseCount}} 份</strong></div><div>有效回答<strong data-testid="cross-answered">{{summary.answeredCount}} 份</strong></div><div>跳过 / 到达未答<strong>{{summary.skippedCount}} / {{summary.unansweredCount}}</strong></div></div><p class="muted">汇总生成于 {{new Date(summary.generatedAt).toLocaleString('zh-CN')}}。{{asOf?`原文/频数快照时点：${new Date(asOf).toLocaleString('zh-CN')}；翻页保持各自第一页快照。`:''}}</p><p v-if="!summary.eligibleResponseCount" class="panel">当前范围没有符合版本的答卷。</p>
<section v-if="'optionCounts' in summary" class="panel"><h2>选项频数</h2><div class="table-wrap"><table><thead><tr><th>选项</th><th>回答次数</th><th>占有效回答</th></tr></thead><tbody><tr v-for="o in summary.optionCounts" :key="o.optionId"><td>{{o.label}}</td><td>{{o.count}}</td><td>{{o.percentage===null?'暂无':`${o.percentage}%`}}</td></tr></tbody></table></div></section>
<section v-if="'average' in summary" class="panel cross-number-summary"><h2>数值汇总</h2><p>均值 <strong data-testid="cross-average">{{summary.average??'暂无'}}</strong> · 最小 {{summary.min??'暂无'}} · 最大 {{summary.max??'暂无'}}</p><ul><li v-for="(b,i) in summary.bins" :key="i">{{b.lower===null?'(-∞':`${b.upper===null?'(':'['}${b.lower}`}}, {{b.upper??'+∞'}}{{b.upperInclusive?']':')'}}：{{b.count}} 份</li></ul><h3>精确值频数</h3><ul><li v-for="row in frequency" :key="row.value">{{row.value}}：{{row.count}} 份</li></ul><p v-if="!frequency.length">暂无数值回答。</p><button v-if="frequencyCursor" class="secondary" :disabled="busy||needsReload" @click="more('distribution')">更多数值频数</button></section>
<section v-if="raw.length||['text','number'].includes(version?.content.type??'')" class="panel"><h2>原始有效回答</h2><p v-if="!raw.length">暂无有效回答。</p><ul class="library-rows"><li v-for="row in raw" :key="row.responseId+row.instanceId"><span class="answer-text">{{row.value}}</span><small>发布 v{{row.publishedVersion}} · {{new Date(row.submittedAt).toLocaleString('zh-CN')}}</small></li></ul><button v-if="answerCursor" class="secondary" :disabled="busy||needsReload" @click="more('answers')">更多原文回答</button></section></template></section></template>
